:root {
  --color-bg: #1a3a4a;
  --color-surface: #f0ebe0;
  --color-header-bg: #1a3a4a;
  --color-header-text: #f0ebe0;
  --color-accent: #e07b2a;
  --color-badge-bg: #e07b2a;
  --color-badge-text: #ffffff;
  --color-text-primary: #1a3a4a;
  --color-text-secondary: #5a7a8a;
  --color-rule-bg: #e8f0f4;
  --color-rule-border: #b0cdd8;
  --color-footer-bg: #1a3a4a;
  --color-footer-text: #f0ebe0;
  --color-cert-bg: #2e7d52;
  --color-cert-text: #ffffff;
  --color-divider: #c8d8e0;
}

article.briefing-card {
  width: 440px;
  background-color: var(--color-surface);
  border-radius: 10px;
  overflow: hidden;
  border: 2px solid var(--color-bg);
}

.card-header {
  display: flex;
  align-items: center;
  gap: 10px;
  background-color: var(--color-header-bg);
  padding: 10px 14px;
}

.card-icon {
  font-size: 24px;
  line-height: 1;
}

.card-title-group {
  flex: 1;
}

.card-title {
  font-size: 16px;
  font-weight: 700;
  color: var(--color-header-text);
  margin: 0;
  line-height: 1.2;
}

.card-subtitle {
  font-size: 11px;
  color: var(--color-accent);
  margin: 0;
  font-weight: 500;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.card-badge {
  background-color: var(--color-badge-bg);
  color: var(--color-badge-text);
  font-size: 11px;
  font-weight: 700;
  padding: 3px 9px;
  border-radius: 20px;
  letter-spacing: 0.04em;
}

.route-info {
  display: flex;
  border-bottom: 1.5px solid var(--color-divider);
}

.route-item {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 7px 6px;
  gap: 2px;
  border-right: 1.5px solid var(--color-divider);
}

.route-item:last-child {
  border-right: none;
}

.route-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--color-text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.route-value {
  font-size: 12px;
  font-weight: 700;
  color: var(--color-text-primary);
  text-align: center;
}

.rules-section {
  padding: 8px 14px;
}

.rules-title {
  font-size: 10px;
  font-weight: 700;
  color: var(--color-text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin: 0 0 6px 0;
}

.rules-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.rule-item {
  display: flex;
  align-items: center;
  gap: 8px;
  background-color: var(--color-rule-bg);
  border: 1px solid var(--color-rule-border);
  border-radius: 5px;
  padding: 5px 10px;
}

.rule-icon {
  font-size: 14px;
  line-height: 1;
  flex-shrink: 0;
}

.rule-text {
  font-size: 12px;
  color: var(--color-text-primary);
  font-weight: 500;
  line-height: 1.3;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background-color: var(--color-footer-bg);
  padding: 8px 14px;
}

.guide-info {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.guide-label {
  font-size: 10px;
  color: var(--color-accent);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.guide-name {
  font-size: 13px;
  font-weight: 700;
  color: var(--color-footer-text);
}

.cert-badge {
  background-color: var(--color-cert-bg);
  border-radius: 5px;
  padding: 5px 10px;
}

.cert-text {
  font-size: 11px;
  font-weight: 700;
  color: var(--color-cert-text);
  letter-spacing: 0.03em;
}
